@gene('Z176a', 'which option kinds to list: never wards; casts only with a slot ready and a foe or camp close', parents=['s1'])
def consider(kind: Num) -> Bool:
    if kind == WARD:
        return False
    if kind == CAST:
        if not (slot_ready(0) or slot_ready(1)):
            return False
        return any(dist(u.pos, me().pos) <= 5 for u in enemies()) or any(dist(u.pos, me().pos) <= 5 for u in camps())
    return True
